import java.util.*;

// Path segment: (integer, replicaId) pair
record Segment(int path, String replicaId) implements Comparable<Segment> {
    @Override
    public int compareTo(Segment other) {
        int pathCompare = Integer.compare(this.path, other.path);
        if (pathCompare != 0) return pathCompare;
        return this.replicaId.compareTo(other.replicaId);
    }
}

final class PositionId implements Comparable<PositionId> {
    private final List<Segment> segments;

    public PositionId(List<Segment> segments) {
        this.segments = List.copyOf(segments);
    }

    public List<Segment> segments() { return segments; }

    @Override
    public int compareTo(PositionId other) {
        int minLen = Math.min(segments.size(), other.segments.size());
        for (int i = 0; i < minLen; i++) {
            int cmp = segments.get(i).compareTo(other.segments.get(i));
            if (cmp != 0) return cmp;
        }
        return Integer.compare(segments.size(), other.segments.size());
    }

    // Generate a position ID strictly between `before` and `after`.
    // Uses a simple strategy: if there's room at the same depth, pick a middle int.
    // Otherwise extend by one level with this replicaId.
    public static PositionId between(PositionId before, PositionId after, String replicaId) {
        List<Segment> pathBefore = (before == null) ? List.of(new Segment(0, replicaId)) : before.segments;
        List<Segment> pathAfter = (after == null)  ? List.of(new Segment(Integer.MAX_VALUE, replicaId)) : after.segments;

        List<Segment> result = new ArrayList<>();
        int depth = 0;
        while (true) {
            int b = depth < pathBefore.size() ? pathBefore.get(depth).path() : 0;
            int a = depth < pathAfter.size()  ? pathAfter.get(depth).path()  : Integer.MAX_VALUE;

            if (a - b > 1) {
                // Room at this depth — pick a middle value
                result.add(new Segment((b + a) / 2, replicaId));
                return new PositionId(result);
            }
            // No room — copy the `before` segment and descend
            result.add(new Segment(b, depth < pathBefore.size() ? pathBefore.get(depth).replicaId() : replicaId));
            depth++;
            // Safety: prevent infinite recursion (unlikely in practice)
            if (depth > 100) {
                result.add(new Segment(Integer.MAX_VALUE / 2, replicaId));
                return new PositionId(result);
            }
        }
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof PositionId p && segments.equals(p.segments);
    }

    @Override
    public int hashCode() { return segments.hashCode(); }
}

// A single character in the CRDT document.
// `deleted = true` means it's a tombstone — kept for ordering but not rendered.
final class CharNode {
    final char value;
    final PositionId positionId;
    final String originReplica;
    boolean deleted = false;

    public CharNode(char value, PositionId positionId, String originReplica) {
        this.value = value;
        this.positionId = positionId;
        this.originReplica = originReplica;
    }
}

enum OpType { INSERT, DELETE }

// Immutable operation broadcast to all replicas.
record Operation(
    String opId,              // replicaId + counter — globally unique
    OpType type,
    PositionId positionId,
    char value,               // ignored for DELETE
    String originReplica,
    long lamportClock
) {}

import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.ConcurrentHashMap;

class Document {
    private final TreeMap<PositionId, CharNode> chars = new TreeMap<>();
    private final String replicaId;
    private final AtomicLong opCounter = new AtomicLong();
    private final AtomicLong lamportClock = new AtomicLong();
    private final Set<String> seenOps = ConcurrentHashMap.newKeySet();

    public Document(String replicaId) {
        this.replicaId = replicaId;
    }

    // ── Local insert at visible index ────
    // Returns the Operation to broadcast to other replicas.
    public synchronized Operation insertLocal(int visibleIndex, char c) {
        if (visibleIndex < 0 || visibleIndex > getLength())
            throw new InvalidOperationException("Index out of range: " + visibleIndex);

        // Find the PositionIds of the neighbors at `visibleIndex - 1` and `visibleIndex`
        // (skipping tombstones)
        PositionId before = findVisibleAt(visibleIndex - 1);
        PositionId after  = findVisibleAt(visibleIndex);

        PositionId newPos = PositionId.between(before, after, replicaId);
        CharNode node = new CharNode(c, newPos, replicaId);
        chars.put(newPos, node);

        long clock = lamportClock.incrementAndGet();
        String opId = replicaId + ":" + opCounter.incrementAndGet();
        Operation op = new Operation(opId, OpType.INSERT, newPos, c, replicaId, clock);
        seenOps.add(opId);
        return op;
    }

    // ── Local delete at visible index ────
    public synchronized Operation deleteLocal(int visibleIndex) {
        PositionId pos = findVisibleAt(visibleIndex);
        if (pos == null)
            throw new InvalidOperationException("No char at index " + visibleIndex);

        CharNode node = chars.get(pos);
        node.deleted = true;

        long clock = lamportClock.incrementAndGet();
        String opId = replicaId + ":" + opCounter.incrementAndGet();
        Operation op = new Operation(opId, OpType.DELETE, pos, '\0', replicaId, clock);
        seenOps.add(opId);
        return op;
    }

    // ── Apply a remote operation ─────────
    // Idempotent: applying the same op twice is a no-op.
    public synchronized void apply(Operation op) {
        if (!seenOps.add(op.opId())) return;  // already applied

        // Update lamport clock — max of ours and theirs, plus 1
        lamportClock.updateAndGet(curr -> Math.max(curr, op.lamportClock()) + 1);

        switch (op.type()) {
            case INSERT -> {
                // If two replicas generate the same PositionId concurrently (extremely unlikely
                // with replicaId tiebreaker), first-write-wins via TreeMap semantics.
                chars.putIfAbsent(op.positionId(),
                    new CharNode(op.value(), op.positionId(), op.originReplica()));
            }
            case DELETE -> {
                CharNode node = chars.get(op.positionId());
                if (node != null) node.deleted = true;
                // If the char doesn't exist yet, we log but accept —
                // in a correct system with causal delivery, this shouldn't happen.
            }
        }
    }

    // ── Render visible text (skipping tombstones) ──
    public synchronized String getText() {
        StringBuilder sb = new StringBuilder();
        for (CharNode n : chars.values()) {
            if (!n.deleted) sb.append(n.value);
        }
        return sb.toString();
    }

    public synchronized int getLength() {
        int count = 0;
        for (CharNode n : chars.values()) {
            if (!n.deleted) count++;
        }
        return count;
    }

    // Find the PositionId of the Nth visible character (-1 = before start, length = after end)
    private PositionId findVisibleAt(int visibleIndex) {
        if (visibleIndex < 0) return null;
        int count = 0;
        for (CharNode n : chars.values()) {
            if (n.deleted) continue;
            if (count == visibleIndex) return n.positionId;
            count++;
        }
        return null; // index >= length
    }
}

class OperationRouter {
    private final Map<String, ReplicaSession> replicas = new ConcurrentHashMap<>();

    public void register(ReplicaSession session) {
        replicas.put(session.getReplicaId(), session);
    }

    public void unregister(String replicaId) {
        replicas.remove(replicaId);
    }

    // Fan out an op to all replicas except the origin
    public void broadcast(Operation op) {
        for (Map.Entry<String, ReplicaSession> e : replicas.entrySet()) {
            if (!e.getKey().equals(op.originReplica())) {
                e.getValue().receiveRemote(op);
            }
        }
    }
}

class ReplicaSession {
    private final String replicaId;
    private final Document document;
    private final OperationRouter router;
    private final List<DocumentListener> listeners = new CopyOnWriteArrayList<>();

    public ReplicaSession(String replicaId, OperationRouter router) {
        this.replicaId = replicaId;
        this.document = new Document(replicaId);
        this.router = router;
        router.register(this);
    }

    // ── User types a character ─────────
    public void type(int index, char c) {
        Operation op = document.insertLocal(index, c);
        notifyListeners();
        router.broadcast(op);
    }

    // ── User deletes a character ──────
    public void delete(int index) {
        Operation op = document.deleteLocal(index);
        notifyListeners();
        router.broadcast(op);
    }

    // ── Remote op arrives from another replica ──
    public void receiveRemote(Operation op) {
        document.apply(op);
        notifyListeners();
    }

    public String getText() { return document.getText(); }
    public String getReplicaId() { return replicaId; }

    // Observer for UI updates
    public void addListener(DocumentListener l) { listeners.add(l); }
    private void notifyListeners() {
        String text = document.getText();
        for (DocumentListener l : listeners) l.onDocumentChanged(text);
    }
}

interface DocumentListener {
    void onDocumentChanged(String newText);
}

OperationRouter router = new OperationRouter();
ReplicaSession alice = new ReplicaSession("alice", router);
ReplicaSession bob   = new ReplicaSession("bob", router);

// Both start with empty doc
alice.type(0, 'H');   // Alice: H
// Broadcast happens — Bob now sees H
bob.type(1, 'i');     // Bob: Hi (appended to Alice's H)
// Now both replicas see "Hi"

assert alice.getText().equals("Hi");
assert bob.getText().equals("Hi");

// Concurrent edit at same position — both preserved
ReplicaSession carol = new ReplicaSession("carol", router);
// All three have "Hi"

// Alice types 'A' at position 1 (between H and i)
// Bob types 'B' at position 1 (also between H and i) — concurrent!
Operation aliceOp = alice.type(1, 'A');  // Alice's local: HAi
Operation bobOp = bob.type(1, 'B');      // Bob's local: HBi

// After both ops propagate, all three replicas converge to the same
// text — either "HABi" or "HBAi" (decided by replicaId tiebreaker in
// PositionId.between). The key is: ALL replicas see the same result.

// CRDT guarantee: identical final state regardless of op delivery order
